toolScript:
const video = document.getElementById('camera-feed');
        const canvas = document.getElementById('analysis-canvas');
        const ctx = canvas.getContext('2d');
        let isRunning = false;
        let isPaused = false;
        let blinkCount = 0;
        let lastBlinkTime = 0;
        let fixationCount = 0;
        let sessionStart = null;
        let sessionTimer = null;
        let analysisTimer = null;
        let lastEyeState = 'open';
        let eyeOpenTime = 0;
        let blinkRates = [];

        async function startTracking() {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({
                    video: { facingMode: 'user', width: 640, height: 480 }
                });
                video.srcObject = stream;
                document.getElementById('start-overlay').style.display = 'none';
                document.getElementById('fixation-point').style.display = 'block';
                document.getElementById('metrics-dashboard').classList.remove('hidden');

                isRunning = true;
                sessionStart = Date.now();
                startSessionTimer();
                startAnalysis();
            } catch (err) {
                alert('Camera access denied. Please allow camera access to use this tool.');
                console.error(err);
            }
        }

        function startSessionTimer() {
            sessionTimer = setInterval(() => {
                if (!isPaused) {
                    const elapsed = Math.floor((Date.now() - sessionStart) / 1000);
                    const minutes = Math.floor(elapsed / 60);
                    const seconds = elapsed % 60;
                    document.getElementById('session-time').textContent =
                        `${minutes}:${seconds.toString().padStart(2, '0')}`;
                }
            }, 1000);
        }

        function startAnalysis() {
            canvas.width = video.videoWidth || 640;
            canvas.height = video.videoHeight || 480;

            function analyze() {
                if (!isRunning || isPaused) {
                    analysisTimer = requestAnimationFrame(analyze);
                    return;
                }

                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                const data = imageData.data;

                let totalBrightness = 0;
                let eyeRegionTop = Math.floor(canvas.height * 0.3);
                let eyeRegionBottom = Math.floor(canvas.height * 0.45);
                let leftEyeX = Math.floor(canvas.width * 0.25);
                let rightEyeX = Math.floor(canvas.width * 0.65);
                let eyeWidth = 60;
                let eyeHeight = 20;

                let leftEyeBrightness = 0;
                let rightEyeBrightness = 0;
                let leftEyePixels = 0;
                let rightEyePixels = 0;

                for (let y = eyeRegionTop; y < eyeRegionBottom; y++) {
                    for (let x = leftEyeX - eyeWidth / 2; x < leftEyeX + eyeWidth / 2; x++) {
                        let idx = (y * canvas.width + x) * 4;
                        let brightness = (data[idx] + data[idx + 1] + data[idx + 2]) / 3;
                        leftEyeBrightness += brightness;
                        leftEyePixels++;
                    }
                    for (let x = rightEyeX - eyeWidth / 2; x < rightEyeX + eyeWidth / 2; x++) {
                        let idx = (y * canvas.width + x) * 4;
                        let brightness = (data[idx] + data[idx + 1] + data[idx + 2]) / 3;
                        rightEyeBrightness += brightness;
                        rightEyePixels++;
                    }
                }

                let avgEyeBrightness = (leftEyeBrightness / leftEyePixels + rightEyeBrightness / rightEyePixels) / 2;

                let currentEyeState = avgEyeBrightness > 80 ? 'open' : 'closed';

                if (currentEyeState === 'open' && lastEyeState === 'closed') {
                    let timeSinceLastBlink = Date.now() - lastBlinkTime;
                    lastBlinkTime = Date.now();
                    blinkCount++;

                    if (timeSinceLastBlink > 500 && timeSinceLastBlink < 2000) {
                        let minutesElapsed = (Date.now() - sessionStart) / 60000;
                        let currentRate = Math.round(blinkCount / Math.max(minutesElapsed, 0.1));
                        blinkRates.push(currentRate);
                        if (blinkRates.length > 10) blinkRates.shift();

                        let avgRate = blinkRates.reduce((a, b) => a + b, 0) / blinkRates.length;
                        document.getElementById('blink-rate').textContent = Math.round(avgRate);

                        fixationCount++;
                        document.getElementById('fixation-count').textContent = fixationCount;

                        updateCognitiveLoad(avgRate);
                        updateFatigueLevel(avgRate);
                        updateBreakRecommendation(avgRate);
                    }
                }

                lastEyeState = currentEyeState;

                let fixationPoint = document.getElementById('fixation-point');
                fixationPoint.style.left = (leftEyeX + (rightEyeX - leftEyeX) * 0.5) + 'px';
                fixationPoint.style.top = ((eyeRegionTop + eyeRegionBottom) / 2) + 'px';

                analysisTimer = requestAnimationFrame(analyze);
            }

            analyze();
        }

        function updateCognitiveLoad(blinkRate) {
            let loadLevel = 50;
            if (blinkRate < 5) loadLevel = 85;
            else if (blinkRate < 10) loadLevel = 70;
            else if (blinkRate < 15) loadLevel = 50;
            else if (blinkRate < 20) loadLevel = 30;
            else loadLevel = 15;

            document.getElementById('cognitive-indicator').style.left = loadLevel + '%';

            let loadText = loadLevel > 70 ? 'High' : loadLevel > 40 ? 'Moderate' : 'Low';
            document.getElementById('load-value').textContent = loadText;
        }

        function updateFatigueLevel(blinkRate) {
            let fatigue = 'Low';
            if (blinkRate > 20) fatigue = 'High';
            else if (blinkRate > 15) fatigue = 'Moderate';
            else fatigue = 'Low';

            document.getElementById('fatigue-level').textContent = fatigue;
        }

        function updateBreakRecommendation(blinkRate) {
            let message = '';
            if (blinkRate < 5) {
                message = 'Deep focus detected. Take a 5-minute break in 10 minutes to maintain performance.';
            } else if (blinkRate > 20) {
                message = 'High fatigue detected. Consider taking a break now or in the next 5 minutes.';
            } else {
                message = 'Cognitive load is manageable. Continue working and check back in 15 minutes.';
            }
            document.getElementById('break-message').textContent = message;
        }

        function pauseSession() {
            isPaused = !isPaused;
            document.getElementById('pause-btn').textContent = isPaused ? 'Resume' : 'Pause';
        }

        function resetSession() {
            isRunning = false;
            isPaused = false;
            blinkCount = 0;
            fixationCount = 0;
            blinkRates = [];
            lastBlinkTime = Date.now();
            lastEyeState = 'open';

            clearInterval(sessionTimer);
            cancelAnimationFrame(analysisTimer);

            if (video.srcObject) {
                video.srcObject.getTracks().forEach(track => track.stop());
            }

            document.getElementById('start-overlay').style.display = 'flex';
            document.getElementById('fixation-point').style.display = 'none';
            document.getElementById('metrics-dashboard').classList.add('hidden');
            document.getElementById('blink-rate').textContent = '--';
            document.getElementById('fixation-count').textContent = '--';
            document.getElementById('session-time').textContent = '0:00';
            document.getElementById('fatigue-level').textContent = '--';
            document.getElementById('load-value').textContent = '--';
            document.getElementById('cognitive-indicator').style.left = '50%';
            document.getElementById('pause-btn').textContent = 'Pause';
        }

        document.addEventListener('keydown', (e) => {
            if (e.code === 'Space' && isRunning) {
                e.preventDefault();
                pauseSession();
            }
        });
